 1| /**
 2|  * receive-order: the first step. It copies the order the desk was handed
 3|  * into the run's state, one field per key, so every later step reads only
 4|  * the field it needs.
 5|  *
 6|  * Why copy: the input of a run is frozen and not tracked; a key in state is
 7|  * tracked, so the record can show which step used it.
 8|  * Example: input `{ order: { orderId: 'A-1', lines: [...] } }` → `orderId = 'A-1'`.
 9|  */
10| 
11| export const purpose = 'Copy the incoming order into the run, one field per key.';
12| 
13| /** @param {any} scope */
14| export function run(scope) {
15|   const { order } = scope.$getArgs();
16|   scope.orderId = order.orderId;
17|   scope.customerId = order.customerId;
18|   scope.shipRegion = order.shipRegion;
19|   scope.billingRegion = order.billingRegion;
20|   scope.shipMethod = order.shipMethod;
21|   scope.couponCode = order.couponCode ?? '';
22|   scope.lines = order.lines.map((line) => ({ sku: line.sku, qty: line.qty }));
23| }
